using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Set up two option instances ---

// 1) Options that know about our types (default reflection-based resolver)
var fullOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    WriteIndented = true
};

// 2) Options with a source-gen context that only knows about int
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = IntOnlyContext.Default,
    WriteIndented = true
};

// ---------------------------------------------------------------
// 1. GetTypeInfo<T>()  –  strongly-typed, throws if unavailable
// ---------------------------------------------------------------
JsonTypeInfo<Person> personInfo = fullOptions.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for Person: {personInfo.Type.Name}");

var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// ---------------------------------------------------------------
// 2. TryGetTypeInfo()  –  probe without throwing
// ---------------------------------------------------------------

// Case A: metadata IS available
if (fullOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    var typed = (JsonTypeInfo<Person>)found!;
    var person = JsonSerializer.Deserialize(json, typed)!;
    Console.WriteLine($"\nProbe succeeded – deserialized: {person}");
}

// Case B: metadata is NOT available (limited resolver doesn't know Person)
if (limitedOptions.TryGetTypeInfo(typeof(Person), out _))
{
    Console.WriteLine("Unexpectedly found Person metadata!");
}
else
{
    Console.WriteLine("\nProbe correctly reported: no Person metadata in limitedOptions.");
}

// ---------------------------------------------------------------

public record Person(string Name, int Age);

[JsonSerializable(typeof(int))]
internal partial class IntOnlyContext : JsonSerializerContext;

